import{_ as t,o as s,c as a,ag as r}from"./chunks/framework.BXn5fPR3.js";const g=JSON.parse('{"title":"HTTP: Discovery & routing","description":"","frontmatter":{},"headers":[],"relativePath":"http/discovery.md","filePath":"http/discovery.md"}'),n={name:"http/discovery.md"};function i(o,e,l,d,c,u){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="http-discovery-routing" tabindex="-1">HTTP: Discovery &amp; routing <a class="header-anchor" href="#http-discovery-routing" aria-label="Permalink to &quot;HTTP: Discovery &amp; routing&quot;">​</a></h1><h2 id="discovery-layer" tabindex="-1"><code>discovery_layer</code> <a class="header-anchor" href="#discovery-layer" aria-label="Permalink to &quot;`discovery_layer`&quot;">​</a></h2><p>The discovery layer: how the player finds other devices and is found, covering the announcements and searches behind &#39;speakers see each other on the network&#39;.</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>mdns:</strong> mDNS controller on RZonePlayer (m_spMdnsController); &#39;%s.local&#39; hostname construct (&#39;Failed construct mdns hostname&#39;); refreshMdnsRegistration; log /opt/log/mdnsd.log; &#39;new cert updating mDNS service [%s]&#39;</li><li><strong>spotify_connect:</strong> _spotify-connect._tcp service registered/unregistered dynamically (&#39;Registering Spotify Connect mDNS service&#39;); MdnsSpotifyService ../anacapa-1.0/oc/zone/zoneplayer/mdns_spotify_service.cxx; SpotifyMDNSRequest events</li><li><strong>ssdp:</strong> RMSearchNotifyHandler select-thread handles SSDP M-SEARCH/NOTIFY; dedup vs mDNS: &#39;handleDefunctZP %s reason %s IGNORED from MDNS - discovered by SSDP&#39; and inverse</li><li><strong>dedup_policy:</strong> a zone-player defunct signal is ignored when the same ZP is discovered via the other discovery channel (mDNS-primary if SSDP-unseen, SSDP-primary if mDNS-unseen)</li><li><strong>todo:</strong> <code>Established: the mDNS controller on RZonePlayer, Spotify Connect service registration, SSDP handler, and the cross-channel defunct-dedup policy are all documented.</code>, <code>Still unknown: the dedup policy&#39;s arbitration details (which channel wins under simultaneous discovery) and the mDNS refresh cadence are sketched only.</code>, <code>Next step: trace the defunct-signal arbitration logic in handleDefunctZP.</code></li></ul></details><h2 id="ssdp-discovery" tabindex="-1"><code>ssdp_discovery</code> <a class="header-anchor" href="#ssdp-discovery" aria-label="Permalink to &quot;`ssdp_discovery`&quot;">​</a></h2><p>Device-discovery announcements and searches: the classic find-each-other protocol where speakers announce presence, search for peers, and log who answered. It&#39;s the older discovery layer alongside the Sonos-specific mechanisms.</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>wire:</strong> M-SEARCH * HTTP/1.1 + HOST:239.255.255.250 + USN: + ssdp:alive/ssdp:byebye; &#39;Sent MSEARCH reply to %s:%u&#39;; &#39;%s unicast MSEARCH from %s&#39;</li><li><strong>headers:</strong> X-RINCON-{HOUSEHOLD,BOOTSEQ,PROXY,VARIANT,REASON} extension headers; MX: search window</li><li><strong>signing:</strong> HMAC-signed M-SEARCH: X-SONOS-SIG: %s + X-Sonos-MS-Sig: headers; &#39;signature HMAC init failed&#39;/&#39;Failed to calculate/add M-SEARCH signature&#39;/&#39;base64 encoding failed&#39;; signed manifests (&#39;Got manifest with invalid signature&#39;, &#39;&lt;!-- SIGNATURE:&#39;)</li><li><strong>handler:</strong> RMSearchNotifyHandler thread + disHandleMSearchAsync dispatch; &#39;Failed to setup MSearchNotifyHandler&#39;</li><li><strong>dedup:</strong> dual-discovery: &#39;handleDefunctZP %s reason %s IGNORED from MDNS - discovered by SSDP&#39;/&#39;from SSDP - discovered by MDNS but not SSDP&#39;</li><li><strong>containers:</strong> x-rincon-cpcontainer:{RDCPA,RDCPI,<em>}:</em> grammar; &#39;Unknown old Rhapsody x-rincon-cpcontainer&#39;</li><li><strong>outbound_templates:</strong><ul><li><strong>alive:</strong> 0x10eef678: NOTIFY * HTTP/1.1 | HOST: 239.255.255.250:1900 | CACHE-CONTROL: max-age = %u | LOCATION: %s | NT: %s | NTS: ssdp:alive | SERVER: %s | USN: %s | %s(trailer)</li><li><strong>byebye:</strong> 0x10eef5fc: NOTIFY * HTTP/1.1 | HOST: 239.255.255.250:1900 | NT: %s | NTS: ssdp:byebye | SERVER: %s | USN: %s | %s(trailer) - note: byebye omits CACHE-CONTROL/LOCATION</li><li><strong>msearch_response:</strong> 0x10eef97c: HTTP/1.1 200 OK | CACHE-CONTROL: max-age = %u | EXT: | LOCATION: %s | SERVER: %s | ST: %s | USN: %s | %s(trailer) - the unicast reply to inbound M-SEARCH</li><li><strong>outbound_msearch:</strong> 0x10eea4f4 = ssdp_signed_msearch template (MAN: &quot;ssdp:discover&quot;, MX:%d, ST:%s, USER-AGENT:%s + signature trailer)</li><li><strong>notes:</strong> alive/byebye/response trailer %s is the signature block (signed SSDP); all four are format literals confirmed at the listed .rodata addresses</li></ul></li></ul></details><h2 id="ssdp-signed-msearch" tabindex="-1"><code>ssdp_signed_msearch</code> <a class="header-anchor" href="#ssdp-signed-msearch" aria-label="Permalink to &quot;`ssdp_signed_msearch`&quot;">​</a></h2><p>Signed M-search: the authenticated form of discovery search, a signed variant protecting the exchange.</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>wire:</strong> M-SEARCH * HTTP/1.1\\r\\nHOST: 239.255.255.250:1900\\r\\nMAN: &quot;ssdp:discover&quot;\\r\\nMX: %d\\r\\nST: %s\\r\\nUSER-AGENT: %s\\r\\n%s\\r\\n (trailer = signature block)</li><li><strong>signature:</strong> HMAC over request -&gt; base64 (&#39;M-SEARCH signature HMAC init failed&#39;,&#39;Failed to add M-SEARCH signature&#39;); inbound verify: &#39;hmac sig verify error&#39;; keys hmacDigest/hmac</li><li><strong>response_headers:</strong> <code>BOOTID.UPNP.ORG: %s</code>, <code>CONFIGID.UPNP.ORG: %d</code>, <code>CACHE-CONTROL: max-age = %u</code></li></ul></details><h2 id="target-udn-routing" tabindex="-1"><code>target_udn_routing</code> <a class="header-anchor" href="#target-udn-routing" aria-label="Permalink to &quot;`target_udn_routing`&quot;">​</a></h2><p>Target-UDN routing: how requests addressed to a specific device ID get routed, which is the mechanism directing commands to the right unit.</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>header:</strong> X-SONOS-TARGET-UDN: uuid:%s + targetUDN param: directs a SOAP action to a specific bonded-zone member UDN</li><li><strong>semantics:</strong> multi-device action routing: the coordinator/group proxy forwards actions to the target member identified by UDN; pairs w/ MobileDeviceUDN/playerUDN/HTPrimaryUDN identity fields</li></ul></details><h2 id="assoctracker" tabindex="-1"><code>assoctracker</code> <a class="header-anchor" href="#assoctracker" aria-label="Permalink to &quot;`assoctracker`&quot;">​</a></h2><p>The association tracker: it watches which network devices the player is associated with, feeding the connectivity-state data diagnostics use.</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>semantics:</strong> Wi-Fi station-association tracking</li></ul></details><h2 id="gena-internals" tabindex="-1"><code>gena_internals</code> <a class="header-anchor" href="#gena-internals" aria-label="Permalink to &quot;`gena_internals`&quot;">​</a></h2><p>The internals of classic eventing: how subscriptions are installed and validated (including pre-installed IDs and URL forms), how notifications are sequenced, and how the subscription list is kept clean.</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>name:</strong> GENA internals + per-service LastChange schemas</li><li><strong>description:</strong> Subscription machinery vocabulary: SID preinstall (&#39;Attempting to preinstall SID=%u&#39;, &#39;?sid=0&#39; URL form), status fields SubscribedEvents/LogicalSID/UPnPSID/NotifyErrors, sender/source pair upnpeventing_sender+upnpeventing_source, AVTStateLastChangedEvent event name, and the &lt;LastChange&gt;%s&lt;/LastChange&gt; wrapper emitted per service. Per-service LastChange payload schemas not enumerated.</li><li><strong>evidence:</strong><ul><li>type: firmware, binary: anacapad, build: 86.10-80260, address: 0x10e9b408, notes: Attempting to preinstall SID</li><li>type: firmware, binary: anacapad, build: 86.10-80260, address: 0x10f0c580, notes: &lt;LogicalSID&gt;</li><li>type: firmware, binary: anacapad, build: 86.10-80260, address: 0x10f00cb8, notes: &lt;NotifyErrors&gt;</li><li>type: firmware, binary: anacapad, build: 86.10-80260, address: 0x10e89d80, notes: &lt;LastChange&gt;</li><li>type: firmware, binary: anacapad, build: 86.10-80260, address: 0x10ed1c6c, notes: &lt;Event xmlns=&quot;urn:schemas-sonos-com:metadata-1-0/Queue/&quot;&gt;: proprietary Queue LastChange</li><li>type: firmware, binary: anacapad, build: 86.10-80260, address: 0x10ed1cd0, notes: &lt;QueueID val=&quot;%.20s&quot;&gt; + QueueOwnerID/UpdateID/Curated elements</li><li>type: firmware, binary: anacapad, build: 86.10-80260, address: 0x10eb29e8, notes: AVT LastChange envelope with r: namespace + full element sequence</li></ul></li><li><strong>lastchange_schemas:</strong><ul><li><strong>RCS:</strong> &lt;Event xmlns=&quot;urn:schemas-upnp-org:metadata-1-0/RCS/&quot;&gt;&lt;InstanceID val=&quot;0&quot;&gt;...: standard UPnP RCS event envelope</li><li><strong>AVT:</strong> &lt;Event xmlns=&quot;urn:schemas-upnp-org:metadata-1-0/AVT/&quot; xmlns:r=&quot;urn:schemas-rinconnetworks-com:metadata-1-0/&quot;&gt; then elements in order: TransportState, CurrentPlayMode, CurrentCrossfadeMode, NumberOfTracks, CurrentTrack, CurrentSection (non-standard), CurrentTrackURI, CurrentTrackDuration, CurrentTrackMetaData, r:EnqueuedTransportURI, r:EnqueuedTransportURIMetaData, PlaybackStorageMedium, AVTransportURI, AVTransportURIMetaData, NextAVTransportURI, NextAVTransportURIMetaData: all as &lt;X val=&quot;...&quot;&gt; attribute-value form</li><li><strong>Queue:</strong> proprietary Sonos namespace urn:schemas-sonos-com:metadata-1-0/Queue/ (NOT a UPnP standard schema. Elements: &lt;QueueID val=&quot;%.20s&quot;&gt; (20-char truncated), &lt;QueueOwnerID val=&quot;%s&quot;/&gt;, &lt;UpdateID val=&quot;%u&quot;/&gt;, &lt;Curated val=&quot;...&quot;&gt;) the Curated flag matches the SavedQueue store schema</li></ul></li><li><strong>notes:</strong> AVT envelopes carry the r: extension namespace for Sonos fields; Queue events live in a Sonos-private namespace (schemas-sonos-com, not rinconnetworks): clients parsing LastChange must handle all three namespaces; val=&quot;&quot; attribute form used throughout</li><li><strong>todo:</strong> <code>Established: the subscription machinery vocabulary, the three event namespaces, and the per-service LastChange schemas are documented.</code>, <code>Still unknown: the notify-delivery internals (resend on NotifyErrors, subscription expiry) are sketched at vocabulary level only.</code>, <code>Next step: trace the upnpeventing sender&#39;s delivery and retry path.</code></li></ul></details>',19)])])}const m=t(n,[["render",i]]);export{g as __pageData,m as default};
